-- Directory creation approval is reserved for administrators.
CREATE OR REPLACE FUNCTION public.admin_review_directory_team_request(p_request_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare r public.directory_team_requests%rowtype; l_id uuid; ok boolean; begin select public.is_current_user_admin_or_moderator() into ok; if not coalesce(ok,false) then raise exception 'Admin access required'; end if; if p_status not in ('approved','rejected') then raise exception 'Invalid status'; end if; if p_status='approved' and not exists (select 1 from public.admin_roles ar where ar.user_id=(select auth.uid()) and lower(trim(coalesce(ar.role,'')))='admin') then raise exception 'Only admins may approve directory team requests' using errcode='42501'; end if; select * into r from public.directory_team_requests where id=p_request_id for update; if not found then raise exception 'Request not found'; end if; if p_status='approved' then if r.league_name is not null and length(trim(r.league_name))>0 then insert into public.leagues(name,country,level,season,source,active) values(trim(r.league_name),trim(r.country),'Requested Directory League','2026-27','HoopCheck member request',true) on conflict do nothing; select id into l_id from public.leagues where name=trim(r.league_name) and country=trim(r.country) limit 1; end if; insert into public.teams(name,country,city,league_name,league_id,source,active) select trim(r.team_name),trim(r.country),nullif(trim(r.city),''),nullif(trim(r.league_name),''),l_id,'HoopCheck member request',true where not exists(select 1 from public.teams t where lower(t.name)=lower(trim(r.team_name)) and lower(coalesce(t.country,''))=lower(trim(r.country))); end if; update public.directory_team_requests set status=p_status,reviewer_id=auth.uid(),reviewer_note=p_note,reviewed_at=now() where id=p_request_id; return true; end; $function$;

revoke all on function public.admin_review_directory_team_request(uuid,text,text) from public,anon;
grant execute on function public.admin_review_directory_team_request(uuid,text,text) to authenticated,service_role;
